import{z as s,x as n,o as l,c as B,q as t,j as E,D as e,d as i,s as o,S as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"CFG 用于语言模型","description":"","frontmatter":{"title":"CFG 用于语言模型","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cfg-llm.md","filePath":"llm/cfg-llm.md","lastUpdated":1791413859000}'),p={name:"llm/cfg-llm.md"};function A(c,a,d,g,h,C){const m=n("Mermaid");return l(),B("div",null,[a[2]||(a[2]=t('<h1 id="cfg-用于语言模型" tabindex="-1">CFG 用于语言模型 <a class="header-anchor" href="#cfg-用于语言模型" aria-label="Permalink to &quot;CFG 用于语言模型&quot;">​</a></h1><div class="epigraph"><p>把有条件与无条件下一步分布的对数差放大，可以在不改权重的前提下加强提示的控制力；过强则会偏离模型原来的语言流形。</p><footer>—— Sanchez et al., Stay on topic with Classifier-Free Guidance, 2023</footer></div><p><a href="/llm/repetition-penalty">上一课</a>在解码期改已出现 token 的 logits，打断短循环，不改变训练分布。缺口是提示仍是软约束：模型可以「听见」指令，仍在长文本里滑回无条件闲聊先验。扩散里的无分类器引导用有条件与无条件预测做外推；Sanchez 等人把同一线性组合接到自回归 logits 上。本课写语言模型上的 CFG：\\(\\gamma\\) 如何沿条件减无条件走得更远，以及它与对比解码、对比搜索不是同一机制。不重推 presence / frequency 的加法项。注意不是文法约束里的 CFG。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>提示是软约束。模型可以在概率上「听见」系统指令，仍在长文本里滑回无条件的闲聊先验。加长提示、重复指令、提高 logit bias，都是在同一条条件分布上加压，没有一条明确的「远离无条件」方向。扩散 CFG 的经验是：无条件预测给出先验，有条件减去先验再放大，等于沿条件梯度走得更远。语言模型的下一步已经是一个词表分布，同一几何可以写在 logit 空间。</p><p>无条件支路必须可定义。空字符串、仅 BOS、或「空系统 + 空用户」都是候选，它们给出的 \\(p(\\cdot\\mid\\emptyset)\\) 并不相同，引导方向也就不同。负提示（写明「不要」的属性）把无条件换成「带负条件」的分布，外推方向变成远离不想要的属性，而不是远离空先验。两种用法共用同一公式，语义完全取决于第二条前向看见什么。</p><p><span class="marginnote">术语翻译：语言模型版的 CFG，就是每写一个词之前让模型「带着题猜一遍、不带题猜一遍」，把两份打分的差放大——带题时更可能的词被推得更高，不带题也爱说的「口头禅」被压下去。权重一个不动，只动采样时的打分。</span></p><h3 id="引导强度与分布外推" tabindex="-1">引导强度与分布外推 <a class="header-anchor" href="#引导强度与分布外推" aria-label="Permalink to &quot;引导强度与分布外推&quot;">​</a></h3><p>记有条件 logits 为 \\(\\ell^c\\)，无条件为 \\(\\ell^u\\)。标准混合是</p> \\[\\ell^{\\mathrm{CFG}} = \\ell^u + \\gamma\\,(\\ell^c - \\ell^u) = \\gamma\\,\\ell^c + (1-\\gamma)\\,\\ell^u. \\]<p>\\(\\gamma=1\\) 退回普通条件生成；\\(\\gamma\\gt 1\\) 沿 \\(c-u\\) 外推；\\(\\gamma=0\\) 是无条件。有人把公式写成 \\((1+\\gamma)\\ell^c-\\gamma\\ell^u\\)，只是把强度的零点从 \\(1\\) 挪到 \\(0\\)，实现时要对齐文档。外推不是概率意义下的几何平均：softmax 之前的线性组合会改变相对排序，也可能把原来的第二名打成第一。强度过大时，分布会离开训练时见过的条件边际，表现为突然的重复或罕见词——与过大的频率惩罚类似，都是把质量推到流形外。</p><p><span class="marginnote">直觉类比：\\(\\gamma\\) 像「按题作答 vs 自由发挥」的配比旋钮——\\(\\gamma=1\\) 全按题答，\\(\\gamma=0\\) 完全自由发挥，\\(\\gamma\\gt 1\\) 是比按题答更用力地按题答。拧过 2 以后，用力过猛的答案开始出现奇怪的重复与罕见词，因为已经答到训练时没见过的区域。</span></p><p><span class="marginnote">CFG 的第二条前向必须与第一条共享除提示以外的已生成前缀。只在第一步做引导、后续只走有条件，等于只在开篇推一把。只共享用户提示、系统提示不同步，引导方向会漂。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每一步对当前前缀做两次（或一次 batch 维为 \\(2\\) 的）前向：条件侧输入完整提示加已写 token，无条件侧输入空条件加同一已写 token。得到 \\(\\ell^c,\\ell^u\\) 后按 \\(\\gamma\\) 混合，再接温度、截断、停用。KV 缓存要为两条序列分别维护，或把两条写进同一 batch 的不同槽。草稿模型上的 CFG 不能替代目标上的 CFG：投机若只在草稿侧引导，目标校验看到的是未引导分布，接受规则对的不是用户以为的那个 \\(p\\)。</p><p>负提示把 \\(\\ell^u\\) 换成 \\(\\ell^{-}\\)。公式仍是 \\(\\ell^u+\\gamma(\\ell^c-\\ell^{-})\\) 的形式，几何上是「靠近 \\(c\\)、远离负条件」。空条件 CFG 加强「像在回应用户」；负提示 CFG 加强「不要像这段描述」。两者可以同时做（三条前向），成本更高，方向在词表上可能冲突，需要把强度拆开而不是共用一个 \\(\\gamma\\)。</p><h3 id="与对比解码、对比搜索的位置" tabindex="-1">与对比解码、对比搜索的位置 <a class="header-anchor" href="#与对比解码、对比搜索的位置" aria-label="Permalink to &quot;与对比解码、对比搜索的位置&quot;">​</a></h3><p>Li 等人的对比解码用小模型当「业余」分布，用 \\(\\ell_{\\mathrm{expert}}-\\ell_{\\mathrm{amateur}}\\) 压掉小模型也会的平庸续写，对象是 <em>另一个网络</em>。CFG 的两条支路是 <em>同一网络、不同提示</em>。Su 的 <a href="/llm/contrastive-search">Contrastive Search</a> 用自身隐状态的最大相似度当退化项，对象是 <em>已经写出的表示</em>，且通常走 \\(\\arg\\max\\) 而不是采样。三条线都在打「泛化、重复、不贴题」，机制分别是提示差、模型能力差、上下文表示差。不要把 \\(\\gamma\\) 抄到对比搜索的 \\(\\alpha\\) 上。</p>',18)),(l(),E(r,null,{default:e(()=>[o(m,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22%E5%B7%B2%E7%94%9F%E6%88%90%E5%89%8D%E7%BC%80%22%5D%20--%3E%20C%5B%22%E6%9D%A1%E4%BB%B6%E5%89%8D%E5%90%91%EF%BC%9A%E6%8F%90%E7%A4%BA%20%2B%20%E5%89%8D%E7%BC%80%22%5D%0A%20%20PRE%20--%3E%20U%5B%22%E6%97%A0%E6%9D%A1%E4%BB%B6%20%2F%20%E8%B4%9F%E6%8F%90%E7%A4%BA%E5%89%8D%E5%90%91%22%5D%0A%20%20C%20--%3E%20M%5B%22%E2%84%93%20%E2%86%90%20u%20%2B%20%CE%B3(c%20%E2%88%92%20u)%22%5D%0A%20%20U%20--%3E%20M%0A%20%20M%20--%3E%20S%5B%22%E6%B8%A9%E5%BA%A6%E4%B8%8E%E6%88%AA%E6%96%AD%E9%87%87%E6%A0%B7%22%5D%0A%20%20S%20--%3E%20PRE%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>在 log 域，CFG 近似在做</p> \\[\\log p_\\gamma(v\\mid c) \\propto \\gamma\\log p(v\\mid c) + (1-\\gamma)\\log p(v\\mid \\emptyset). \\]<p>\\(\\gamma\\gt 1\\) 时，有条件相对无条件更高的 token 被进一步抬高，更低的被进一步压低。若某词在提示下比在空条件下更可能出现，它会主导采样；若某词是语言模型的无条件口头禅，只要它在空条件下更高，就会被抑制。这就是「更贴题」的来源：贴的是 <em>相对空先验的超额对数概率</em>，不是相对真值。提示本身若含糊，超额方向也含糊，加大 \\(\\gamma\\) 只会更自信地执行含糊指令。</p><p>计算上，decode 步的主要成本仍是读 KV。两条前向几乎加倍带宽，墙钟接近 \\(2\\times\\)，除非把 batch 拼在一起摊启动开销。对已经带宽打满的大模型，CFG 是昂贵的采样器，不是免费的控制度。Prefill 阶段两条提示长度不同，不能共用同一段 KV；实现上无条件支路往往更短，算力不对称。</p><p><span class="marginnote">\\(\\gamma\\) 不是温度的倒数。温度对混合后的 logits 再缩放；CFG 先改方向，再让温度决定锋利程度。只报一个「CFG 1.5」而不报 \\(T\\) 与截断，分布不能复现。</span></p><h3 id="空条件如何构造" tabindex="-1">空条件如何构造 <a class="header-anchor" href="#空条件如何构造" aria-label="Permalink to &quot;空条件如何构造&quot;">​</a></h3><p>「无条件」在聊天模板里并不空。若条件侧有系统角色与工具定义，无条件侧仍塞进同一套角色包装、只挖掉用户问题，引导会加强「像助手」而不是「回答这个问题」。若无条件侧连角色也不给，引导会夹带「像助手 vs 像裸模型」的方向。必须把第二条序列的构造写成产品约定。多轮对话里，无条件支路是丢掉全部用户轮、只留系统，还是每轮都丢掉当前问题、保留历史，会改变「贴题」相对于哪一段历史。后者更贵，前者更容易在长对话里把旧题当先验压掉。</p>',8)),(l(),E(r,null,{default:e(()=>[o(m,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20NUL%5B%22%E6%97%A0%E6%9D%A1%E4%BB%B6%E6%94%AF%E8%B7%AF%E7%9C%8B%E8%A7%81%E4%BB%80%E4%B9%88%22%5D%20--%3E%20E1%5B%22%E7%A9%BA%E5%AD%97%E7%AC%A6%E4%B8%B2%20%2F%20%E4%BB%85%20BOS%22%5D%0A%20%20NUL%20--%3E%20E2%5B%22%E7%95%99%E7%B3%BB%E7%BB%9F%E8%A7%92%E8%89%B2%EF%BC%8C%E6%8C%96%E6%8E%89%E7%94%A8%E6%88%B7%E9%97%AE%E9%A2%98%22%5D%0A%20%20NUL%20--%3E%20E3%5B%22%E8%BF%9E%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%E4%B9%9F%E4%B8%A2%E6%8E%89%22%5D%0A%20%20E1%20--%3E%20D1%5B%22%E5%BC%95%E5%AF%BC%E6%96%B9%E5%90%91%EF%BC%9A%E8%B4%B4%E4%BB%BB%E5%8A%A1%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20E2%20--%3E%20D2%5B%22%E5%BC%95%E5%AF%BC%E6%96%B9%E5%90%91%EF%BC%9A%E8%B4%B4%E3%80%8C%E5%83%8F%E5%8A%A9%E6%89%8B%E3%80%8D%E8%AF%AD%E6%B0%94%22%5D%0A%20%20E3%20--%3E%20D3%5B%22%E9%A3%8E%E9%99%A9%EF%BC%9A%E5%BC%95%E5%AF%BC%E8%B6%8A%E5%BC%BA%E8%B6%8A%E5%81%8F%E7%A6%BB%E5%AE%89%E5%85%A8%E7%BA%A6%E6%9D%9F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>CFG 不保证事实正确，只保证相对所选无条件更极端。错误事实若只在有条件提示下被强化（提示里已经暗示了错答案），引导会更错。安全策略若写在系统提示里，空条件支路丢掉系统提示等于在引导里 <em>削弱</em> 安全方向——这是实现漏洞，不是论文声称的能力。正确做法是让安全前缀出现在两条支路，只把任务条件放进差分。</p><p><span class="marginnote">常见误区：初学者容易把系统提示当成「只给条件侧看的背景」。若无条件支路丢掉系统提示，安全约束只存在于加号一侧——引导每加强一分任务方向，就相对削弱一分安全方向；正确做法是安全前缀两侧都放，只对任务条件做差分。</span></p><p>与 nucleus、min-\\(p\\) 叠用时，应在混合后的 \\(\\ell^{\\mathrm{CFG}}\\) 上截断。两条支路分别截断再混合，几何意义不清，也容易空核。停用词与 stop 字符串仍按最终采样的字符串匹配，与是否引导无关。评测要对齐：学术报告里的 \\(\\gamma\\) 曲线通常不含聊天模板；产品里模板一变，同一 \\(\\gamma\\) 的主观控制度会变。</p><p>不要为了省一次前向而用「把无条件 logits 固定成均匀」或「用小模型冒充无条件」。那已经不是 Sanchez 等人的 CFG，而是另一种对比解码，需要单独验证。训练期的 CFG（在 dropout 条件上联合训）属于扩散与部分多模态模型的配方，与推理期对已训好的 LLM 做两条前向不是同一档实验。</p><p><span class="marginnote">出处是 Sanchez et al., 2023，把 Ho 与 Salimans 的无分类器引导接到 LM logits。不要把本篇的 CFG 写成上下文无关文法，也不要把 \\(\\gamma\\) 写成分类器梯度。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>语言模型上的 CFG 用同一模型的有条件与无条件（或负提示）logits 做线性外推，加强提示方向。</li><li>\\(\\gamma=1\\) 为普通条件生成；\\(\\gamma\\gt 1\\) 沿条件减无条件的方向走得更远，也更容易离开语言流形。</li><li>无条件支路看见什么，决定「贴题」相对哪一个先验；聊天模板必须写进协议。</li><li>每步约两次前向，decode 带宽墙下成本接近翻倍。</li><li>它与对比解码（大小模型差）和对比搜索（上下文表示差）不是同一机制。</li><li>安全前缀应出现在两条支路，只对任务条件做差分，否则引导会削弱系统约束。</li><li>出处：Sanchez et al., <em>Stay on topic with Classifier-Free Guidance</em>, 2023。扩散侧原型见 Ho &amp; Salimans 的无分类器引导。</li></ul>',8))])}const _=s(p,[["render",A]]);export{u as __pageData,_ as default};
